async function checkBackendHealth(): Promise<boolean> {
  try {
    const response = await fetch(`${BASE_URL}/`, { method: 'GET' });
    return response.ok;
  } catch (error) {
    console.error('Backend connection failed:', error);
    return false;
  }
}

/**
