import React, { useState, useEffect } from 'react';
import { Task, getTasks, createTask, updateTaskStatus, deleteTask } from '../api/tasks';

interface TaskListProps {}

const STATUS_CYCLE: Record<Task['status'], Task['status']> = {
  pending: 'in_progress',
  in_progress: 'done',
  done: 'pending',
};

const getStatusColor = (status: Task['status']): string => {
  switch (status) {
    case 'pending': return '#ffcc00';
    case 'in_progress': return '#00ccff';
    case 'done': return '#00cc00';
    default: return '#ccc';
  }
};

export const TaskList: React.FC<TaskListProps> = () => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [newTitle, setNewTitle] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadTasks();
  }, []);

  const loadTasks = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getTasks();
      setTasks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const handleAddTask = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle.trim()) return;

    try {
      const newTask = await createTask({ title: newTitle });
      setTasks([...tasks, newTask]);
      setNewTitle('');
    } catch (err) {
      alert('Failed to add task: ' + (err instanceof Error ? err.message : ''));
    }
  };

  const handleCycleStatus = async (task: Task) => {
    const nextStatus = STATUS_CYCLE[task.status];
    try {
      const updatedTask = await updateTaskStatus(task.id, nextStatus);
      setTasks(tasks.map(t => t.id === task.id ? updatedTask : t));
    } catch (err) {
      alert('Failed to update status: ' + (err instanceof Error ? err.message : ''));
    }
  };

  const handleDelete = async (taskId: string) => {
    if (!window.confirm('Are you sure you want to delete this task?')) {
      return;
    }
    try {
      await deleteTask(taskId);
      setTasks(tasks.filter(t => t.id !== taskId));
    } catch (err) {
      alert('Failed to delete task: ' + (err instanceof Error ? err.message : ''));
    }
  };

  if (loading) return <div>Loading tasks...</div>;
  if (error) return <div style={{ color: 'red' }}>Error: {error}</div>;

  return (
    <div className="task-list-container">
      <h2>Tasks</h2>

      <form onSubmit={handleAddTask} style={{ marginBottom: '20px' }}>
        <input
          type="text"
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
          placeholder="New task title"
          style={{ padding: '8px', marginRight: '8px' }}
        />
        <button type="submit" disabled={!newTitle.trim()}>Add Task</button>
      </form>

      <ul style={{ listStyleType: 'none', padding: 0 }}>
        {tasks.length === 0 && <li>No tasks yet.</li>}
        {tasks.map(task => (
          <li key={task.id} style={{ border: '1px solid #ddd', padding: '10px', marginBottom: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div>
              <strong>{task.title}</strong>
              <br />
              <small>Status: 
                <span 
                  onClick={() => handleCycleStatus(task)} 
                  style={{ cursor: 'pointer', marginLeft: '5px', padding: '2px 6px', borderRadius: '4px', color: 'white', backgroundColor: getStatusColor(task.status) }}
                >
                  {task.status.replace('_', ' ')}
                </span>
              </small>
              <br />
              <small>Assignee: {task.assignee || 'Unassigned'}</small>
              <br />
              <small>Created: {new Date(task.createdAt).toLocaleString()}</small>
            </div>
            <button 
              onClick={() => handleDelete(task.id)} 
              style={{ backgroundColor: '#ff4444', color: 'white', border: 'none', padding: '5px 10px', cursor: 'pointer', borderRadius: '4px' }}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

